class Solution:
    def decodeMessage(self, key: str, message: str) -> str:
        mp = {}
        nxt = 0
        for ch in key:
            if ch != ' ' and ch not in mp:
                mp[ch] = chr(ord('a') + nxt)
                nxt += 1
        return ''.join(mp.get(ch, ' ') for ch in message)

