class Solution {
public:
    string decodeMessage(string key, string message) {
        vector<int> mp(128, -1);
        char nxt = 'a';
        for (char ch : key)
            if (ch != ' ' && mp[ch] == -1) mp[ch] = nxt++;
        string res;
        for (char ch : message) res.push_back(ch == ' ' ? ' ' : (char)mp[ch]);
        return res;
    }
};

c.java:
class Solution {
    public String decodeMessage(String key, String message) {
        int[] mp = new int[128];
        Arrays.fill(mp, -1);
        char nxt = 'a';
        for (char ch : key.toCharArray())
            if (ch != ' ' && mp[ch] == -1) mp[ch] = nxt++;
        StringBuilder sb = new StringBuilder();
        for (char ch : message.toCharArray()) sb.append(ch == ' ' ? ' ' : (char) mp[ch]);
        return sb.toString();
    }
}

