var decodeMessage = function(key, message) {
    const mp = {};
    let nxt = 0;
    for (const ch of key)
        if (ch !== ' ' && !(ch in mp)) mp[ch] = String.fromCharCode(97 + nxt++);
    return [...message].map(ch => mp[ch] ?? ' ').join('');
};
